/* gemma4_tok_gate -- Gemma 4's tokenizer graded against HF tokenizers (L338).  Model-free; seconds.
 *
 * Gemma 4 ships a SentencePiece-style BPE tokenizer.json: a Replace(' ' -> U+2581) normaliser, a Split(" ") the
 * normaliser leaves nothing to match (a run is one piece), a BPE model over characters with <0xXX> byte fallback, a
 * Replace / ByteFallback / Fuse decoder.  bpe_tokenizer runs it as its "gemma4" row (the SentencePiece-BPE pipeline:
 * one merge loop with the byte-level rows, symbols per character).  Goldens: tests/test-vectors/gemma4/, generated by
 * tests/gemma4/gen_tok_goldens.py from tokenizers' Tokenizer (meta.json records the versions and the input hashes).
 *
 *   T1 adversarial strings        encode(text) == HF ids (the shared strings, Gemma's cases, random)
 *   T2 span guard                 encode(text, client spans) == tokenizers' components with added tokens cut only
 *                                 outside the spans
 *   T3 every scalar value         per-4096-codepoint chunk: count + sha1(ids) == HF
 *   T4 calibration corpus         count + sha1(ids) == HF   (--calib)
 *   T5 token bytes                token_bytes(id) == HF decode([id]) on 3601 ids (a lone byte-fallback byte >= 0x80
 *                                 decodes to U+FFFD in HF; the engine keeps the byte, so those compare as U+FFFD)
 *   T6 the facts                  the pattern is "gemma4"; 262144 ids; stop ids = generation_config's [1, 106, 50]
 *
 * usage: gemma4_tok_gate --tok DIR --vectors DIR [--calib FILE]
 *        DIR = the checkpoint's tokenizer.json + generation_config.json */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <string>
#include <vector>

#include "bpe_gate_util.h"

/* T3's context for one codepoint c (gen_tok_goldens.py sweep_text) */
static std::string sweep_context(const std::string &c) { return "x" + c + c + c + " " + c + "1'" + c + "Ab" + c + "\n"; }

/* T5: each sampled id's stored bytes against HF's decode of it alone */
static void t5_decode(const bpe_tokenizer *t, const std::string &dir) {
    const pyjson_value v = load_json(dir + "/tok_decode.json");
    int n = 0, bad = 0;
    for (const pyjson_value &e : v.a) {
        const int id = atoi(e.get("id")->num.c_str());
        const std::string &want = e.get("text")->s;
        size_t len = 0;
        const char *b = bpe_tokenizer_token_bytes(t, id, &len);
        std::string got = b ? std::string(b, len) : std::string();
        if (got.size() == 1 && (unsigned char)got[0] >= 0x80) got = "\xef\xbf\xbd";   /* HF: a lone byte -> U+FFFD */
        n++;
        if (got != want && bad++ < 5) fail("T5 id %d: bytes '%s' != HF decode '%s'", id, got.c_str(), want.c_str());
    }
    CHECK(bad == 0, "T5 %d of %d token byte strings differ from HF decode", bad, n);
    printf("T5 token bytes: %d ids, %d differ\n", n, bad);
}

int main(int argc, char **argv) {
    std::string tok_dir, vec_dir, calib;
    for (int i = 1; i < argc; i++) {
        const std::string a = argv[i];
        if (a == "--tok" && i + 1 < argc) tok_dir = argv[++i];
        else if (a == "--vectors" && i + 1 < argc) vec_dir = argv[++i];
        else if (a == "--calib" && i + 1 < argc) calib = argv[++i];
        else {
            fprintf(stderr, "usage: gemma4_tok_gate --tok DIR --vectors DIR [--calib FILE]\n");
            return 2;
        }
    }
    if (tok_dir.empty() || vec_dir.empty()) {
        fprintf(stderr, "usage: gemma4_tok_gate --tok DIR --vectors DIR [--calib FILE]\n");
        return 2;
    }
    std::string tj, gj;
    if (!read_file(tok_dir + "/tokenizer.json", &tj) || !read_file(tok_dir + "/generation_config.json", &gj)) {
        fprintf(stderr, "gemma4_tok_gate: %s must hold tokenizer.json and generation_config.json\n", tok_dir.c_str());
        return 2;
    }
    char err[300];
    bpe_tokenizer *t = bpe_tokenizer_load_hf(tj.data(), tj.size(), gj.data(), gj.size(), err, sizeof err);
    if (!t) {
        fprintf(stderr, "gemma4_tok_gate: the tokenizer refused: %s\n", err);
        return 1;
    }
    const std::vector<int> &stop = bpe_tokenizer_stop_ids(t);
    CHECK(!strcmp(bpe_tokenizer_pattern(t)->name, "gemma4"), "T6 pattern %s", bpe_tokenizer_pattern(t)->name);
    CHECK(bpe_tokenizer_n_tokens(t) == 262144, "T6 %d ids", bpe_tokenizer_n_tokens(t));
    CHECK(stop.size() == 3 && stop[0] == 1 && stop[1] == 106 && stop[2] == 50, "T6 stop ids are not [1, 106, 50]");
    printf("tokenizer: %s (gemma4: SentencePiece-BPE, byte fallback), %d ids, stops %d %d %d\n", tok_dir.c_str(),
           bpe_tokenizer_n_tokens(t), stop.size() > 0 ? stop[0] : -1, stop.size() > 1 ? stop[1] : -1,
           stop.size() > 2 ? stop[2] : -1);
    t1_adversarial(t, vec_dir);
    t2_spans(t, vec_dir);
    t3_sweep(t, vec_dir, sweep_context);
    if (!calib.empty()) t4_calib(t, vec_dir, calib);
    t5_decode(t, vec_dir);
    bpe_tokenizer_free(t);
    printf("\ngemma4_tok_gate: %d checks, %s\n", g_checks, g_fail ? "FAIL" : "PASS");
    return g_fail ? 1 : 0;
}
